Object.assign(SNIP,{"l29lenh": "g++ -std=c++17 -Wall -Wextra -g bai.cpp -o bai                       # bật cảnh báo\ng++ -std=c++17 -g -fsanitize=address,undefined bai.cpp -o bai        # bắt lỗi lúc chạy\nvalgrind --leak-check=full ./bai                                       # (Linux) tìm rò rỉ"});PRESET_NOTES["l29"]={"Lỗi: rò rỉ bộ nhớ trong vòng lặp": "Kết quả in ra đúng, nhưng mỗi lần gọi tong để lại một khối trên heap mà không ai trả: con trỏ a mất khi hàm kết thúc. Sau 3 lần gọi có 3 khối bị rò rỉ. Nếu hàm được gọi hàng triệu lần, chương trình sẽ ăn hết RAM. Sửa: delete[] a; trước return, hoặc dùng vector<int> a(n).", "Lỗi: gán đè con trỏ làm mất khối cũ": "Khối #1 (chứa 1) mất con trỏ duy nhất khi p được gán địa chỉ khối #2: không còn cách nào delete nó nữa. delete p chỉ trả khối #2. Sửa: delete p; trước khi gán p = new int(2);.", "Lỗi: dùng vùng nhớ sau khi delete": "p đã được gán nullptr đúng cách, nhưng q vẫn giữ địa chỉ khối #1 vừa bị trả (mũi tên đỏ nét đứt). Trên máy thật, *q có thể in 3, in rác, hoặc làm hỏng dữ liệu của lần new sau. Trình mô phỏng dừng ngay ở dòng này.", "Lỗi: con trỏ trỏ vào biến đã hết phạm vi": "x chỉ sống trong thân vòng for. Ra khỏi vòng, x bị hủy nhưng p vẫn trỏ vào chỗ cũ trên stack: con trỏ treo. Chỗ đó sẽ bị biến khác dùng lại, nên giá trị đọc được là ngẫu nhiên. Sửa: khai báo x bên ngoài vòng lặp, cùng phạm vi với p.", "Lỗi: ghi quá cuối khối heap": "Khối có 3 ô (a[0] đến a[2]) nhưng vòng lặp chạy tới i <= n nên ghi vào a[3]. Trên máy thật lệnh này thường không báo gì mà ghi đè lên thông tin quản lý heap ngay sau khối, và chương trình hỏng ở một lần new hay delete về sau. Sửa: i < n.", "Lỗi: delete hai lần": "giaiPhong đã trả khối, nhưng main không biết điều đó và delete thêm lần nữa: free(): double free detected. Đây là hậu quả của việc không rõ ai là chủ khối nhớ. Sửa: quyết định một nơi duy nhất được delete.", "Sửa: viết lại bằng vector": "Cùng bài toán với ví dụ rò rỉ đầu tiên, nhưng dùng vector: vector tự xin vùng nhớ khi tạo và tự trả khi hàm kết thúc. Không có new nên không có gì để quên delete; cột Heap trống, không có cảnh báo rò rỉ."};EX_HINTS["l29"]=[["Có hai khối được xin: mảng a trong main và mảng s trong tongTienTo.", "tongTienTo trao quyền sở hữu s cho main, nên main phải delete[] cả s lẫn a."], ["lon trỏ vào bên trong khối a. Sau delete[] a, cả a và lon đều thành con trỏ treo.", "Chỉ trả khối khi đã dùng xong mọi con trỏ vào nó: đưa dòng in lên trước delete[]."], ["vector<int> chan; rồi chan.push_back(x) cho mỗi số chẵn: không cần biết trước có bao nhiêu.", "Số âm chẵn cũng có x % 2 == 0 (ví dụ -2 % 2 là 0), nên không cần xử lý riêng."]];
/* ===================== BÀI 29 · Lỗi bộ nhớ thường gặp ===================== */
/* Bài 29 · Lỗi bộ nhớ thường gặp
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P29=[{label:"Lỗi: rò rỉ bộ nhớ trong vòng lặp",input:"",code:"#include <iostream>\nusing namespace std;\n\nint tong(int n) {\n    int* a = new int[n];\n    int s = 0;\n    for (int i = 0; i < n; i++) {\n        a[i] = i + 1;\n        s += a[i];\n    }\n    return s;\n}\n\nint main() {\n    for (int k = 1; k <= 3; k++) {\n        cout << tong(k * 2) << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: gán đè con trỏ làm mất khối cũ",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int* p = new int(1);\n    p = new int(2);\n    cout << *p << \"\\n\";\n    delete p;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: dùng vùng nhớ sau khi delete",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int* p = new int(3);\n    int* q = p;\n    delete p;\n    p = nullptr;\n    cout << *q << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: con trỏ trỏ vào biến đã hết phạm vi",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int* p = nullptr;\n    for (int i = 0; i < 1; i++) {\n        int x = 5;\n        p = &x;\n        cout << *p << \"\\n\";\n    }\n    cout << *p << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: ghi quá cuối khối heap",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n = 3;\n    int* a = new int[n];\n    for (int i = 0; i <= n; i++) {\n        a[i] = i * 10;\n    }\n    cout << a[0] << \"\\n\";\n    delete[] a;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: delete hai lần",input:"",code:"#include <iostream>\nusing namespace std;\n\nvoid giaiPhong(int* p) {\n    delete p;\n}\n\nint main() {\n    int* p = new int(9);\n    cout << *p << \"\\n\";\n    giaiPhong(p);\n    delete p;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Sửa: viết lại bằng vector",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint tong(int n) {\n    vector<int> a(n);\n    int s = 0;\n    for (int i = 0; i < n; i++) {\n        a[i] = i + 1;\n        s += a[i];\n    }\n    return s;\n}\n\nint main() {\n    for (int k = 1; k <= 3; k++) {\n        cout << tong(k * 2) << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"mem"}]}];
const sim29=makeSim2(document.getElementById("sim-l29"),{id:"s29",presets:P29});
makeEx2(document.getElementById("ex-l29"),sim29,[{t:"Sửa rò rỉ bộ nhớ",d:"Chương trình dưới đây nhập n (1 ≤ n ≤ 1000) rồi n số, và in tổng của mỗi tiền tố độ dài 1, 2, …, n trên một dòng. Kết quả đúng nhưng hàm <code>tongTienTo<\/code> làm rò rỉ bộ nhớ. Hãy sửa để mọi khối <code>new<\/code> đều được trả lại.",tests:[{in:"4\n1 2 3 4",out:"1 3 6 10"},{in:"1\n5",out:"5"},{in:"3\n-1 -1 -1",out:"-1 -2 -3"},{in:"5\n10 0 10 0 10",out:"10 10 20 20 30"}],start:"#include <iostream>\nusing namespace std;\n\nint* tongTienTo(const int* a, int n) {\n    int* s = new int[n];\n    s[0] = a[0];\n    for (int i = 1; i < n; i++) s[i] = s[i - 1] + a[i];\n    return s;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    int* a = new int[n];\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int* s = tongTienTo(a, n);\n    for (int i = 0; i < n; i++) cout << s[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",need:/^(?=[\s\S]*delete\s*\[\s*\]\s*s\s*;)(?=[\s\S]*delete\s*\[\s*\]\s*a\s*;)/,needMsg:"Hãy trả cả hai khối: delete[] s; và delete[] a;."},{t:"Sửa lỗi dùng sau khi delete",d:"Chương trình nhập n (1 ≤ n ≤ 1000) rồi n số, in số lớn nhất và vị trí đầu tiên của nó (đếm từ 0). Nó có lỗi dùng vùng nhớ sau khi trả. Hãy sửa.",tests:[{in:"5\n3 9 2 9 4",out:"9 1"},{in:"1\n-5",out:"-5 0"},{in:"3\n1 2 3",out:"3 2"},{in:"4\n7 7 7 7",out:"7 0"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int* a = new int[n];\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int* lon = a;\n    for (int* p = a; p < a + n; p++) {\n        if (*p > *lon) lon = p;\n    }\n    delete[] a;\n    cout << *lon << \" \" << lon - a << \"\\n\";\n    return 0;\n}",need:/cout[^;]*\*\s*lon[^;]*;[\s\S]*delete\s*\[\s*\]\s*a\s*;/,needMsg:"Hãy in kết quả trước, rồi mới delete[] a;."},{t:"Viết lại bằng vector",d:"Nhập n (1 ≤ n ≤ 10<sup>5<\/sup>) rồi n số nguyên. In các số chẵn theo thứ tự xuất hiện (nếu không có, in dòng trống). Viết bằng <code>vector<\/code>, <b>không<\/b> dùng <code>new<\/code>.",tests:[{in:"6\n1 2 3 4 5 6",out:"2 4 6"},{in:"3\n1 3 5",out:""},{in:"4\n-2 0 7 8",out:"-2 0 8"},{in:"1\n10",out:"10"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    // phiên bản cũ dùng int* chan = new int[n]; và quên delete[]\n    // hãy dùng vector<int> chan; và push_back\n    return 0;\n}",need:/^(?![\s\S]*\bnew\b)[\s\S]*vector\s*<\s*int\s*>/,needMsg:"Hãy dùng vector<int> và không dùng new."}]);

makeQuiz("quiz29","score29",[{"q": "Chương trình có lỗi dùng vùng nhớ sau khi delete nhưng chạy thử vẫn in đúng. Kết luận nào đúng?", "o": ["Chương trình đúng", "Lỗi chỉ xảy ra trên Windows", "Vẫn là hành vi không xác định: có thể sai ở lần chạy khác hoặc máy khác", "Trình biên dịch đã tự sửa lỗi"], "a": 2, "e": "Hành vi không xác định có thể trông như đúng. Kết quả đúng một lần không chứng minh được gì."}, {"q": "Lỗi nào thường <b>không<\/b> có triệu chứng gì khi chạy chương trình ngắn?", "o": ["Rò rỉ bộ nhớ", "Trả hai lần", "Dùng nullptr", "Mảng cục bộ 100 MB"], "a": 0, "e": "Rò rỉ chỉ làm RAM tăng dần; với chương trình ngắn hệ điều hành thu hồi hết khi kết thúc nên không thấy gì. Ba lỗi còn lại thường làm chương trình dừng."}, {"q": "Công cụ nào giúp phát hiện “dùng sau khi trả” ngay lúc chạy, kèm số dòng?", "o": ["<code>-O2<\/code>", "<code>-fsanitize=address<\/code>", "<code>-std=c++17<\/code>", "<code>-o bai<\/code>"], "a": 1, "e": "AddressSanitizer chèn kiểm tra vào chương trình và dừng ngay khi truy cập vùng đã trả."}, {"q": "Vì sao giữ <code>int* p = &amp;v[0];<\/code> rồi gọi <code>v.push_back(x)<\/code> là nguy hiểm?", "o": ["push_back xóa v[0]", "Khi đầy, vector chuyển dữ liệu sang khối mới và trả khối cũ, p thành con trỏ treo", "Con trỏ không trỏ được vào vector", "push_back đổi kiểu của v"], "a": 1, "e": "vector giãn bằng cách xin khối mới và trả khối cũ, giống mảng tự giãn ở Bài 28."}]);

